function heroBenefits(branch=false){return `<div class="hero-benefits" aria-label="Коротко о программе Люмини"><a href="${branch?'#program':'#advantages'}"><span class="benefit-mark">✳</span><div><b>Занятия — в тарифе</b><small>По программе выбранной группы</small></div></a><a href="${branch?'#team':'#advantages'}"><span class="benefit-mark">◉</span><div><b>Специалисты рядом</b><small>Психолог, логопед, нейропсихолог</small></div></a><a href="${branch?'#adaptation':'#advantages'}"><span class="benefit-mark">♡</span><div><b>Небольшие группы</b><small>Внимание к темпу ребёнка</small></div></a></div>`}
function advantageIntro(){return `<section class="section advantage-intro" id="advantages"><div class="wrap"><div class="section-head"><div><span class="eyebrow">БОЛЬШЕ, ЧЕМ ПРИСМОТР</span><h2>Пока вы заняты своим днём,<br>у ребёнка — целый мир открытий</h2></div><p>Собрали сильные стороны программы Люмини и показали, что они дают ребёнку и семье.</p></div><div class="advantage-layout"><div class="advantage-visual">${img('tild6331-6138-4862-b062-353563633134-1776858238527-krasno.jpg','Ребёнок выполняет задание карандашом. Кадр из опубликованной галереи Люмини','advantage-photo')}<div class="photo-ticket"><b>Пробовать. Думать. Дружить.</b><span>Развитие через собственный опыт</span></div></div><div class="advantage-accordion"><details open><summary><span><small>01 / ИНТЕРЕС РЕБЁНКА</small>Не один кружок — разные способы раскрыться</span></summary><div class="advantage-answer"><p>Музыка, движение, творчество и исследования дополняют основную программу сада. Ребёнок пробует разное и находит то, что увлекает именно его.</p><p class="parent-gain"><b>Для семьи:</b> меньше отдельных поездок по секциям, больше времени вместе вечером.</p><a class="under" href="/filial-krasnobogatyrskaya-sad#program">Посмотреть содержание программы ↗</a></div></details><details><summary><span><small>02 / МЫШЛЕНИЕ И САМОСТОЯТЕЛЬНОСТЬ</small>Искать решения и не бояться пробовать</span></summary><div class="advantage-answer"><p>ТРИЗ-игры, STEAM и игровая математика учат задавать вопросы, исследовать и находить свои решения. Модель 4К добавляет общение, работу в команде и творчество.</p><p class="parent-gain"><b>Для ребёнка:</b> опыт рассуждать, договариваться и доводить идею до результата.</p><a class="under" href="/filial-krasnobogatyrskaya-sad#program">Как устроены занятия ↗</a></div></details><details><summary><span><small>03 / ВНИМАНИЕ И ПОДДЕРЖКА</small>Воспитатели и специалисты рядом</span></summary><div class="advantage-answer"><p>В материалах Люмини представлены воспитатели, психолог, логопед и нейропсихолог. Это разные роли: ежедневная жизнь группы и профильная работа над навыками.</p><p class="parent-gain"><b>Для семьи:</b> познакомиться с людьми и понять их участие в жизни ребёнка ещё до выбора.</p><a class="under" href="/filial-krasnobogatyrskaya-sad#team">Познакомиться с педагогами ↗</a></div></details><details><summary><span><small>04 / СВОЙ ТЕМП</small>Небольшая группа, место для каждого</span></summary><div class="advantage-answer"><p>Возрастные группы и индивидуальный образовательный маршрут позволяют сочетать общие занятия с разным темпом освоения программы. Для старших дошкольников предусмотрена подготовка к школе и нулевой класс.</p><p class="parent-gain"><b>Для ребёнка:</b> поддержка на своём этапе — от первых игр в группе до школьных задач.</p><a class="under" href="/filial-krasnobogatyrskaya-sad#compatibility">Выбрать программу по возрасту ↗</a></div></details></div></div></div></section>`}
const groupPrograms=[
 {id:'early',label:'Люминяшечки',age:'Ранний возраст',groups:[['Игра и ощущения','Сенсорное развитие','Мелкая моторика','Речь и окружающий мир'],['Музыка и движение','Музыкальное развитие','Физическое развитие','Ритмика и логоритмика'],['Первые открытия','Игровая математика','Конструирование','Опыты в игре']]},
 {id:'middle',label:'Люминяшки / Люминики',age:'Дошкольные группы',groups:[['Думать и исследовать','ТРИЗ-игры','STEAM и опыты','Мышематика / логика'],['Выражать себя','Развитие речи','Музыка и творчество','Театральные занятия'],['Пробовать новое','Конструирование','Английский язык','Движение и координация']]},
 {id:'senior',label:'Люминята / Люминаторы',age:'Старшие дошкольники',groups:[['Готовиться к школе','Обучение грамоте','Математика','Подготовка руки к письму'],['Работать с идеями','ТРИЗ и проекты','Шахматы','Логика и исследование'],['Общаться и выступать','Развитие речи','Командные задачи','Музыка и театр']]},
 {id:'zero',label:'Нулевой класс',age:'Перед первым классом',groups:[['Учебные навыки','Грамота и чтение','Математика','Письмо и графомоторика'],['Самостоятельность','Работа по инструкции','Внимание и саморегуляция','Учебный ритм'],['Содержательный день','Творческие задачи','Проектная деятельность','Движение и общение']]}
];
function program(b){return `<section class="section program-section" id="program"><div class="wrap"><div class="section-head"><div><span class="eyebrow">ЗАНЯТИЯ В САДУ, А ВЕЧЕР — ДЛЯ СЕМЬИ</span><h2>Не нужно выбирать<br>между садом и развитием</h2></div><p>В опубликованной программе сада соединены интеллектуальные, творческие и спортивные направления.</p></div><div class="program-tabs" role="tablist" aria-label="Программы возрастных групп">${groupPrograms.map((g,i)=>`<button type="button" id="group-${g.id}" role="tab" aria-selected="${i===1}" aria-controls="program-${g.id}" tabindex="${i===1?0:-1}" data-group="${g.id}">${g.label}<small>${g.age}</small></button>`).join('')}</div>${groupPrograms.map((g,i)=>`<div class="program-panel" id="program-${g.id}" role="tabpanel" aria-labelledby="group-${g.id}" ${i===1?'':'hidden'}><div class="program-categories">${g.groups.map(([title,...items],j)=>`<article><span class="program-symbol" aria-hidden="true">${['✳','◌','✧'][j]}</span><h3>${title}</h3><ul>${items.map(t=>`<li>${t}</li>`).join('')}</ul></article>`).join('')}</div><div class="program-proof"><b>Как это устроено по дням?</b><p>Здесь будет рабочее расписание группы: время, длительность, педагог и отметка об оплате. Точного расписания в полученных материалах пока нет.</p><a href="#schedule" class="under">Открыть блок расписания ↓</a></div></div>`).join('')}<div class="program-bottom"><p><b>В тарифе:</b> занятия, включённые в программу и договор выбранной группы.</p><p><b>Отдельно:</b> индивидуальные услуги, опции и абонементы центра — по своему перечню.</p></div><p class="source-line">Содержание сгруппировано по опубликованным программам Краснобогатырской. Это обзор направлений, а не утверждённое расписание или расчёт числа включений.</p><div class="schedule-preview" id="schedule"><div><span class="eyebrow">РАСПИСАНИЕ ВАШЕЙ ГРУППЫ</span><h3>Весь день — перед глазами</h3><p>Направления и число занятий за неделю будут показаны отдельно: без сложения программ разных возрастов.</p></div><div class="schedule-empty"><span class="draft-label">НУЖНЫ ДАННЫЕ САДА</span><p>Рабочая неделя ещё не загружена.</p><small>Поля: день · время · занятие · длительность · педагог · включено / дополнительно · период действия.</small></div></div></div></section>`}
function teachers(b){const kras=b.id==='krasno';const people=kras?[['Наталья Елисеева','Воспитатель, педагог раннего развития','10+ лет','Педагогика и психология дошкольного образования. Знакомство с миром через игру и постепенное освоение навыков.'],['Екатерина Житинкина','Педагог нулевого класса','12+ лет','Групповые и индивидуальные занятия: подготовка к школе, игра и творческие задания.'],['Виталий Асмолов','Воспитатель детей дошкольного возраста','10+ лет','Психолого-педагогическое образование и опыт ежедневной работы с детскими группами.']]:[['Ксения Грачева','Старший воспитатель, логопед-дефектолог','7+ лет','Высшее дефектологическое образование; развитие речи и сопровождение образовательной программы.'],['Наталья Кузьмичева','Воспитатель, педагог английского языка','5+ лет','Знакомство с английским через игры и естественное общение.'],['Светлана Журавлева','Воспитатель старшей группы','17+ лет','Высшее педагогическое образование; занятия для развития познавательного интереса.']];return `<section class="section soft" id="team"><div class="wrap"><div class="section-head"><div><span class="eyebrow">ЗА ПРОГРАММОЙ — КОНКРЕТНЫЕ ЛЮДИ</span><h2>Сначала познакомиться.<br>Потом доверить ребёнка.</h2></div><p>Люди важнее общего обещания «опытная команда». Ниже — педагоги из адресного раздела на сайте Люмини.</p></div><div class="teacher-grid">${people.map(([name,role,exp,about],i)=>`<article class="teacher-card"><div class="teacher-top"><span class="teacher-initials" aria-hidden="true">${name.split(' ').map(t=>t[0]).join('')}</span><div><small>ПЕДАГОГИЧЕСКИЙ ОПЫТ*</small><b>${exp}</b></div></div><h3>${name}</h3><p class="teacher-role">${role}</p><p>${about}</p><div class="teacher-tenure"><span>Работа в Lumini и группа</span><b>Будут добавлены после кадровой сверки</b></div></article>`).join('')}</div><p class="source-line">*Опыт по опубликованному разделу «Педагоги», проверка 28.10.2026. Это стаж в профессии, не срок работы в Lumini. Фотографии и назначение по группам требуют согласования.</p><div class="continuity"><div><span class="eyebrow">ЕСЛИ ПРИВЫЧНЫЙ ВОСПИТАТЕЛЬ ОТСУТСТВУЕТ</span><h3>Важно сохранить знакомый ритм</h3><p>Кто подменяет взрослого, как передаются привычки ребёнка и как узнаёт семья — эти вопросы должны быть понятны заранее.</p></div><div><span class="draft-label">ПРОЕКТ ПОРЯДКА · НА СОГЛАСОВАНИИ</span><ol><li>Назначить сотрудника для подмены и познакомить его с группой.</li><li>Передать сведения о привычках, питании и первых днях ребёнка.</li><li>Уведомить семью о замене и ответственном за связь.</li></ol></div></div></div></section>`}
function adaptation(){return `<section class="section" id="adaptation"><div class="wrap"><span class="eyebrow">РАССТАВАНИЕ — ТОЖЕ ЧАСТЬ ЗНАКОМСТВА</span><div class="section-head"><h2>Привыкать к саду<br>в своём темпе</h2><p>Люмини описывает адаптацию с поддержкой психолога. План первых посещений согласуется с семьёй и командой сада.</p></div><div class="steps"><article class="step"><h3>Сначала — о ребёнке</h3><p>Что любит, как засыпает, как переживает расставание. Знакомство начинается с привычек, а не с требования сразу остаться на полный день.</p></article><article class="step"><h3>Первые посещения</h3><p>Длительность, встречающий взрослый и участие специалиста обсуждаются до первого визита.</p></article><article class="step"><h3>Следующий шаг — вместе</h3><p>Обратная связь семье и решение о длительности дня опираются на состояние ребёнка, а не на обещание адаптации за фиксированное число дней.</p></article></div><p class="source-line">Последовательность — проект подачи для согласования с садом. Фактический объём сопровождения и ответственный фиксируются по группе.</p></div></section>`}
function ordinaryDay(b){return `<section class="section day-section" id="day"><div class="wrap"><span class="eyebrow">ВАЖНЫ НЕ ТОЛЬКО ЗАНЯТИЯ</span><div class="section-head"><h2>Обычный день,<br>в котором ребёнку есть место</h2><p>Движение, еда и отдых так же важны, как новые знания. Показываем каждый аспект отдельно.</p></div><div class="day-nav" aria-label="Содержание дня"><span>Игра и занятия</span><span>Прогулка</span><span>Питание</span><span>Сон и отдых</span><span>Встреча с семьёй</span></div><div class="day-evidence-grid"><article><span class="day-number">01</span><h3>Гулять, двигаться,<br>исследовать</h3><p>Родителю важно видеть место прогулки, путь к нему и обычный ритм выходов по сезону.</p><div class="evidence-placeholder"><b>Место и фото прогулок</b><small>Нужны кадры этой площадки, принадлежность территории, сопровождение и фактическая продолжительность.</small></div></article><article><span class="day-number">02</span><h3>Есть с интересом,<br>учитывать привычки</h3><p>Меню обычной недели помогает понять рацион, а разговор до договора — обсудить ограничения и возможные замены.</p><div class="evidence-placeholder"><b>Меню на неделю</b><small>Нужны дата, число приёмов, источник приготовления и согласованные правила индивидуального питания.</small></div></article><article><span class="day-number">03</span><h3>Отдыхать,<br>набирать силы</h3><p>Место сна, время отдыха и действия взрослого, если ребёнок не засыпает, заслуживают отдельного объяснения.</p><div class="evidence-placeholder"><b>Спальня и режим группы</b><small>Нужны фото, время отдыха и принятый садом порядок укладывания.</small></div></article></div><div class="day-callout"><b>На экскурсии можно увидеть весь день, а не только игровую.</b><p>Посмотрите групповую и спальню, обсудите прогулки и меню, познакомьтесь с воспитателями.</p>${btn('Записаться на экскурсию','#excursion')}</div></div></section>`}
function payment(b){return `<section class="section soft" id="price"><div class="wrap"><span class="eyebrow">ПРОЗРАЧНЫЙ РАСЧЁТ ДЛЯ СЕМЬИ</span><div class="section-head"><h2>Понятно, что в программе.<br>Понятно, за что платите.</h2><p>Отдельно показываем месяц, вступительный взнос, первый платёж и платные опции.</p></div><div class="price-layout"><article class="price-card"><span class="pill">${b.name}</span><h3>День в саду<br>с программой развития</h3><div class="price-title">Один расчёт.<br>Все составляющие.</div><dl><div><dt>Ежемесячно</dt><dd>Тариф выбранного режима</dd></div><div><dt>Единоразово</dt><dd>Вступительный взнос</dd></div><div><dt>Дополнительно</dt><dd>Только выбранные платные опции</dd></div><div><dt>Первый платёж</dt><dd>Месяц + взнос + обязательные услуги</dd></div></dl>${btn('Записаться на экскурсию','#excursion','yellow')}</article><div class="payment-evidence"><h3>Развитие уже внутри дня</h3><p>По описанию сада творческие, спортивные и развивающие занятия дополняют основную программу и входят в договор.</p><div class="payment-row"><b>Включённая программа</b><p>Перечень по группе и режиму — в приложении к договору.</p></div><div class="payment-row"><b>Опции отдельно</b><p>Индивидуальные занятия и услуги центра имеют самостоятельные условия.</p></div><div class="payment-row"><b>Пропуск, перерасчёт, возврат</b><p>Показать конкретные пункты действующего договора рядом с расчётом.</p></div><p class="source-line">В этом шаблоне суммы скрыты до согласования единого прайса: в исходных материалах различаются вступительные взносы.</p></div></div></div></section>`}
function communication(){return `<section class="section communication" id="communication"><div class="wrap"><div class="communication-grid"><div><span class="eyebrow">ЕСЛИ ВОЗНИК ВОПРОС</span><h2>Родителю важно<br>быть услышанным</h2><p>Не только фото с занятий, но и понятный разговор о дне ребёнка, его самочувствии и трудностях.</p><a class="under" href="tel:+79251414117">Связаться с садом: +7 (925) 141-41-17 ↗</a></div><div class="contact-process"><span class="draft-label">ПОРЯДОК СВЯЗИ · ПРОЕКТ ДЛЯ СОГЛАСОВАНИЯ</span><div><b>1. Обратиться</b><p>Указать рабочий канал и ответственного за вопросы семьи.</p></div><div><b>2. Получить понятный ответ</b><p>Обозначить часы связи и реальный срок первого ответа.</p></div><div><b>3. Договориться о решении</b><p>Зафиксировать действия, ответственного и способ проверки результата.</p></div><small>Имя руководителя, канал и сроки заполняются после принятия процесса садом. Подтверждённый контакт сейчас — общий телефон.</small></div></div></div></section>`}
function documentsBlock(){return `<section class="section soft" id="documents"><div class="wrap"><span class="eyebrow">ДОКУМЕНТЫ ДО ПРИНЯТИЯ РЕШЕНИЯ</span><div class="section-head"><h2>Договор можно понять<br>без сюрпризов в оплате</h2><p>Состав услуг и правила должны совпадать на сайте, в разговоре с администратором и в подписываемом документе.</p></div><div class="document-grid"><article><span>01 / ОСНОВАНИЕ</span><h3>Сведения<br>об организации</h3><p>Официальные сведения и документы — в существующем разделе сайта.</p><a class="under" href="${ext('/org-info')}">Открыть раздел ↗</a></article><article><span>02 / СТОИМОСТЬ</span><h3>Договор<br>и приложения</h3><p>Обезличенный действующий договор, тариф, включения и доплаты.</p><span class="document-pending">Документ сада ещё не предоставлен</span></article><article><span>03 / ПРАВИЛА</span><h3>Пропуски,<br>перерасчёт, возврат</h3><p>Краткое объяснение с отсылками к пунктам действующего договора.</p><span class="document-pending">Нужны подтверждённые условия</span></article></div></div></section>`}
function parentTrust(){return `<section class="section parent-trust"><div class="wrap"><span class="eyebrow">ЧТО ЦЕНЯТ СЕМЬИ ЛЮМИНИ</span><div class="section-head"><h2>Самое ценное —<br>в обычных днях</h2><p>Темы отзывов, опубликованных на lumini.club. Это впечатления отдельных семей о сети, без переноса на конкретную группу.</p></div><div class="parent-themes"><div><b>Внимательные взрослые</b><p>Родители рассказывают о тёплом отношении и воспитателях, которых дети вспоминают с привязанностью.</p></div><div><b>Интерес к занятиям</b><p>В отзывах ценят творческие, спортивные и развивающие активности в одном месте.</p></div><div><b>Удобство для семьи</b><p>Родители отмечают возможность заниматься в течение дня и освободить вечер от поездок.</p></div></div><a class="under" href="https://lumini.club/">Посмотреть исходные отзывы на сайте Люмини ↗</a></div></section>`}
function home(){return `<section class="hero hero-v2"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">ЛЮМИНИ · ДВА ДЕТСКИХ САДА И ЦЕНТР РАЗВИТИЯ В МОСКВЕ</span><h1>Ребёнку —<br>новые открытия.<br>Вечера —<br>для вашей семьи.</h1><p>В Люмини играют, исследуют, занимаются творчеством и спортом. Развитие уже встроено в день сада — вечер можно оставить для семьи.</p><div class="actions">${btn('Выбрать свой сад','#branches')}${btn('Что даёт Люмини','#advantages','outline')}</div>${heroBenefits()}</div><div class="hero-media">${img('1776858238527-krasno.jpg','Дети с педагогом показывают творческие работы в Люмини','hero-photo',false)}<span class="photo-caption">Сегодня — маленькое открытие. Завтра — «я сам!»</span>${img('-3_nero_ai_image_ups.png','','mascot',false)}</div></div></div></section>${advantageIntro()}<section class="section soft" id="branches"><div class="wrap"><span class="eyebrow">ВАШ МАРШРУТ В ЛЮМИНИ</span><div class="section-head"><h2>Выберите удобный сад.<br>Или любимое занятие.</h2><p>Два сада с программой дня и центр с отдельными студиями — каждый формат на своей странице.</p></div><div class="grid3">${cards()}</div><div class="season"><div><span class="eyebrow" style="margin-bottom:8px">КОГДА У ДЕТЕЙ КАНИКУЛЫ</span><h3>Новые друзья и большие впечатления</h3><p>Сезонные программы клубов — отдельно от обычного режима сада.</p></div><div class="linkrow"><a class="under" href="${ext('/summer-club')}">При детском саде ↗</a><a class="under" href="${ext('/summer-camp')}">Городской клуб ↗</a></div></div></div></section><section class="section" id="approach"><div class="wrap"><div class="section-head"><div><span class="eyebrow">СПОКОЙСТВИЕ СКЛАДЫВАЕТСЯ ИЗ КОНКРЕТНОГО</span><h2>Кто рядом с ребёнком.<br>Как проходит его день.<br>Что входит в оплату.</h2></div><p>На странице сада собраны ответы на вопросы, с которыми семья выбирает место для ребёнка.</p></div><div class="evidence-links"><a href="/filial-krasnobogatyrskaya-sad#team"><span>01</span><h3>Люди,<br>которых вы знаете</h3><p>Педагоги, их опыт, знакомство и первые дни.</p><b>О команде и адаптации ↗</b></a><a href="/filial-krasnobogatyrskaya-sad#day"><span>02</span><h3>День,<br>который вы понимаете</h3><p>Занятия, прогулки, еда и отдых в одном распорядке.</p><b>О жизни группы ↗</b></a><a href="/filial-krasnobogatyrskaya-sad#price"><span>03</span><h3>Условия,<br>с которыми вы согласны</h3><p>Включения, доплаты, первый платёж и договор.</p><b>О стоимости и документах ↗</b></a></div></div></section>${parentTrust()}${addresses()}<section class="section"><div class="wrap banner"><div><span class="eyebrow">ПРИХОДИТЕ ПОЗНАКОМИТЬСЯ</span><h2>Увидеть сад.<br>Почувствовать атмосферу.<br>Задать свои вопросы.</h2><p>Выберите площадку — на экскурсии можно посмотреть помещения, познакомиться с командой и обсудить программу ребёнка.</p></div>${btn('Выбрать филиал','#branches','yellow')}</div></section>${faq()}`}
function detail(b){if(b.id==='melnikova')return legacyDetail(b);return `<div class="wrap breadcrumbs"><a href="/">Главная</a> / ${b.name}</div><section class="hero hero-v2 detail-v2"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">ЧАСТНЫЙ ДЕТСКИЙ САД · КРАСНОБОГАТЫРСКАЯ, 24 · ЖК «ЯУЗА ПАРК»</span><h1>В сад —<br>за открытиями.<br>Домой —<br>с историями.</h1><p>Творчество, движение, исследования и подготовка к школе — в программе дня. Рядом воспитатели и профильные специалисты, а у ребёнка есть пространство пробовать своё.</p><div class="actions">${btn('Записаться на экскурсию','#excursion')}${btn('Посмотреть программу','#program','outline')}</div>${heroBenefits(true)}</div><div class="hero-media">${img(b.image,'Дети с педагогом показывают творческие работы. Люмини, Краснобогатырская.','hero-photo',false)}<span class="photo-caption">У каждого дня — своё «смотри, что я сделал!»</span>${img('-3_nero_ai_image_ups.png','','mascot',false)}</div></div><nav class="subnav" aria-label="Разделы страницы сада"><a href="#price">Стоимость</a><a href="#program">Программа</a><a href="#team">Педагоги</a><a href="#adaptation">Адаптация</a><a href="#day">День ребёнка</a><a href="#communication">Обратная связь</a><a href="#documents">Договор</a></nav></div></section><section class="fit-strip" id="compatibility"><div class="wrap"><div><b>По возрасту и интересам</b><span>От первых игр в группе до нулевого класса</span></div><div><b>Небольшие возрастные группы</b><span>Свой темп внутри общей программы</span></div><div><b>Москва, Краснобогатырская, 24</b><a href="#addresses">Посмотреть адрес и вход ↓</a></div></div></section>${payment(b)}${program(b)}${teachers(b)}${adaptation()}${ordinaryDay(b)}${communication()}${documentsBlock()}${parentTrust()}${faq(true)}${addresses(b)}${form(b)}`}

function center(){return `<section class="section"><div class="wrap"><span class="eyebrow">ЛЮМИНИ · ОТДЕЛЬНЫЙ ФОРМАТ</span><div class="split"><div><h1>Центр развития.<br>Найти своё<br>интересное</h1><p>Спортивные, творческие и развивающие направления. Выберите программу, уточните возраст, расписание и условия посещения.</p><div class="actions">${btn('Посмотреть программы',ext('/detskij-centr'))}${btn('Позвонить в центр','tel:+79258805800','outline')}</div></div>${img('branch-center-CoPGlH.jpg','Изображение из раздела центра развития на lumini.club','split-photo',false)}</div><div class="conditions"><div class="condition"><h3>Программа</h3><p>Что интересно ребёнку и какую задачу решает занятие.</p></div><div class="condition"><h3>Группа и расписание</h3><p>Возраст, педагог и удобное время — по конкретной студии.</p></div><div class="condition"><h3>Условия оплаты</h3><p>Пробное посещение, абонемент и пропуски уточняются отдельно от сада.</p></div></div></div></section>${addresses(branches[2])}${faq()}`}
const tasks=[['01','Автопопап','Убран; первый экран открыт сразу.'],['02','Мобильные тарифы','Обычная сетка, одна колонка на телефоне. Суммы ждут утверждения.'],['03','Навигация филиалов','У каждого сада и центра свой маршрут в шапке, карточках и футере.'],['04','Матрица условий','Необходимо утвердить возраст, часы, режимы, взнос, включения, акции по каждому филиалу.'],['05','Ошибочные URL','Ссылки ведут на /rental, /summer-club и /summer-camp. Реальные 301 требуют доступа к основному сайту и карты переносов.'],['06','Программа и команда','Блоки предусмотрены; нужны фамилии, квалификация, согласия, расписание и договорные включения.'],['07','Архитектура','Главная с краткими и подробными преимуществами; адресная страница сада перестроена по приоритетному дополнению. Существующие URL сохранены.'],['08','Документы и отзывы','Нет выдуманных цитат или лицензий. Нужны проверенные документы, филиальная атрибуция и права на контент.'],['09','Форма','Required, телефон, изменяемый филиал и демосостояния. Реальная отправка и политика оператора не подключены.'],['10','NAP и schema','Подтверждённые адреса и телефоны используются отдельно. Часы и ChildCare JSON-LD отложены до сверки. Шаблон закрыт от индексации.'],['11','Доступность','Семантика, alt, видимый фокус, якоря и мобильное меню. Итоги браузерной проверки — ниже.'],['12','Воронка','Подготовлены события branch_select, tour_form_start, tour_demo_complete, phone_click, route_click. Аналитика и CRM не подключены; клик не равен заявке.'],['13','Домены и индексация','Рабочий сайт и домены не менялись. Нужны права и read-only выгрузка до решения о переносе.'],['14','CRO-пилот','После базовой воронки и подтверждения мест. Рост конверсии не заявляется.'],['15','B2B отдельно','Отдельная /partners; коммерческие условия не придуманы.']];
function notes(){return `<section class="section"><div class="wrap"><span class="eyebrow">ДЛЯ СОГЛАСОВАНИЯ · 28.10.2026</span><h1>Шаблон Люмини:<br>карта внедрения</h1><p>Основание: LUMINI-FULL-REPORT-20261027.pdf, версия 5 от 28.10.2026 16:30 мск, 25 страниц. Приоритетное дополнение на первых пяти страницах учтено в новой версии главной и страницы Краснобогатырской. Это новая частная версия для просмотра; lumini.club не менялся.</p><div class="swatches"><div class="swatch" style="background:#4a2942;color:white">Основной текст / бренд<code>#4A2942</code></div><div class="swatch" style="background:#ffe680">Акцент / действие<code>#FFE680</code></div><div class="swatch" style="background:#d47d9d">Декоративный розовый<code>#D47D9D</code></div></div><h2>Что изменилось по новому отчёту</h2><p>Hero теперь раскрывает пользу программы: занятия внутри дня, профильные специалисты и свой темп. Ниже: конкретные направления по группам, педагоги с опубликованным опытом, адаптация, день ребёнка, обратная связь и договор. Темы чужих отзывов используются как вопросы для проверки, а не как обвинения другим садам или доказанные достоинства Lumini.</p><h2>Преимущество → что ценят → какое опасение снимает</h2><div class="mapping-scroll"><table class="notes-table"><thead><tr><th>Позитив отзывов</th><th>Негатив / опасение</th><th>Польза семьи</th><th>Доказательство</th><th>Статус</th></tr></thead><tbody>${advantageMap.map(r=>`<tr><td>${r.positive}</td><td>${r.concern}</td><td>${r.benefit}</td><td>${r.proof}</td><td>${r.state}</td></tr>`).join('')}</tbody></table></div><h2>Решения по оформлению</h2><p>Главный источник — lumini.club: палитра, шрифт Nunito, оригинальный логотип и персонаж. Сохранены тёплый характер и округлые формы; добавлены читаемая сетка, самостоятельные адресные карточки и спокойная иерархия. Персонаж помогает узнавать бренд; фотографии имеют подписи источника и не выданы за проверенные новые материалы. Refero недоступен (неактивная подписка); для доступности использованы рекомендации craft-details.</p><table class="notes-table"><thead><tr><th>№</th><th>Предложение анализа</th><th>Результат / зависимость</th></tr></thead><tbody>${tasks.map(t=>`<tr>${t.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><h2>Что нужно до рабочего запуска</h2><ul class="list"><li>Филиальная матрица условий и первый платёж. Конфликтующие 20/35 тыс. ₽, 1,3/1,5 года и 07/08 часов не выбраны произвольно.</li><li>Фактическое расписание, адаптация, состав команды, условия питания/сна/прогулок, FAQ по договору, схема входа.</li><li>Подтверждённые сведения о документах, отзывы и разрешения на фотографии. Фотографии с текущего сайта использованы только в закрытом шаблоне.</li><li>Получатель заявок, утверждённая политика/согласие, тестовый контур, аналитика и CRM. Никакие данные формы не отправляются.</li><li>Доступ к основному сайту для переноса, 301, индексации и проверенной филиальной разметки.</li></ul><h2>Проверка шаблона</h2><p id="qa-summary">Проверены маршруты, локальные ресурсы и синтаксис JavaScript. В браузере: главная и Краснобогатырская на 360/390/1440 px без горизонтального переполнения, выбор возрастной программы мышью и стрелками, прямые ссылки на разделы. Демоформа, меню и Escape проверены в первой версии и сохранены. Мобильные заголовки дополнительно уплотнены. Анимации можно отключить; системное уменьшение движения учитывается.</p><div class="actions">${btn('Открыть главную','/')}${btn('Сад Краснобогатырская',branches[0].url,'outline')}</div></div></section>`}
function partners(){return `<section class="section"><div class="wrap"><span class="eyebrow">ОТДЕЛЬНЫЙ МАРШРУТ ДЛЯ B2B</span><h1>Партнёрам Люмини</h1><p>Предложения для организаций обсуждаются отдельно от выбора детского сада. Формат сотрудничества и коммерческие условия требуют согласования.</p><div class="actions">${btn('Обсудить контакт для сотрудничества','tel:+79251414117')}${btn('К выбору сада','/#branches','outline')}</div></div></section>`}
const path=location.pathname.replace(/^\/lumini-preview(?=\/|$)/,'').replace(/\/$/,'')||'/';let b=branches.find(b=>b.url===path);const content=path==='/template-notes'?notes():path==='/partners'?partners():b?.id==='center'?center():b?detail(b):home();document.getElementById('app').innerHTML=(header()+`<main id="main">${content}</main>`+footer()).replace(/(href|src)="\/(?!\/)/g, '$1="/lumini-preview/');if(b)document.title=`${b.name} — Люмини | Шаблон`;
const menu=$('.menu');menu.addEventListener('click',()=>{let open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);$('.navlinks').classList.toggle('open',open);menu.textContent=open?'×':'☰'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){menu.click();menu.focus()}});$('.navlinks').addEventListener('click',e=>{if(e.target.closest('a')&&menu.getAttribute('aria-expanded')==='true')menu.click()});
function event(name,data={}){window.dispatchEvent(new CustomEvent('lumini:analytics',{detail:{name,...data}}))}document.addEventListener('click',e=>{let a=e.target.closest('a');if(!a)return;if(a.href.startsWith('tel:'))event('phone_click',{branch:b?.id||null});if(a.href.includes('yandex.ru/maps'))event('route_click',{branch:b?.id||null});let branch=branches.find(v=>new URL(a.href).pathname===v.url);if(branch)event('branch_select',{branch:branch.id})});const f=$('#tour-form');if(f){let started=false;f.addEventListener('input',()=>{if(!started){event('tour_form_start',{branch:f.branch.value});started=true}});f.addEventListener('submit',e=>{e.preventDefault();let digits=f.phone.value.replace(/\D/g,'');if(digits.length<10||digits.length>15){f.phone.setCustomValidity('Введите номер телефона: от 10 до 15 цифр.');f.phone.reportValidity();f.phone.focus();return}f.phone.setCustomValidity('');let button=f.querySelector('button[type=submit]');button.disabled=true;button.textContent='Проверяем заполнение…';setTimeout(()=>{f.querySelector('.formstatus').textContent='Демонстрация завершена: поля заполнены корректно. Заявка не отправлена. Для реальной записи позвоните '+branches.find(v=>v.id===f.branch.value).phone+'.';button.disabled=false;button.textContent='Записаться на экскурсию ↗';event('tour_demo_complete',{branch:f.branch.value})},450)});f.phone.addEventListener('input',()=>f.phone.setCustomValidity(''))}
// Animation never blocks content or interaction; reduced motion is respected.
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const motionButton=document.createElement('button');motionButton.className='motion-control';motionButton.type='button';motionButton.setAttribute('aria-pressed','false');motionButton.textContent='◌ Анимация включена';document.body.append(motionButton);
let motionOff=reduced.matches;try{motionOff=localStorage.getItem('lumini-motion')==='off'||reduced.matches}catch{}
function applyMotion(){document.body.classList.toggle('motion-off',motionOff);motionButton.setAttribute('aria-pressed',String(motionOff));motionButton.textContent=motionOff?'◌ Анимация выключена':'◌ Анимация включена'}applyMotion();motionButton.addEventListener('click',()=>{motionOff=!motionOff;applyMotion();try{localStorage.setItem('lumini-motion',motionOff?'off':'on')}catch{}});reduced.addEventListener('change',e=>{motionOff=e.matches;applyMotion()});
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -15px 0px'});document.querySelectorAll('.section-head,.grid3>.card,.season,.split>div,.split>.split-photo,.condition,.step,.gallery>*,.banner,.faq details,.formwrap,.address,.map-panel,.price-card,.timeline>div,.hero-benefits>a,.teacher-card,.day-evidence-grid>article,.document-grid>article,.evidence-links>a,.parent-themes>div').forEach((el,i)=>{el.classList.add('reveal');if(el.matches('.card,.condition,.step'))el.style.setProperty('--delay',`${Math.min([...el.parentNode.children].indexOf(el),2)*90}ms`);observer.observe(el)});document.addEventListener('focusin',e=>{let el=e.target.closest('.reveal');if(el)el.classList.add('visible')})}
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);let scheduled=false;function updateProgress(){let max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?scrollY/max:0})`;scheduled=false}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateProgress)}},{passive:true});updateProgress();

// Accessible program selector. Content is a sourced program overview, never a fabricated timetable.
const groupTabs=[...document.querySelectorAll('[data-group]')];function selectGroup(tab){for(const item of groupTabs){const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1;document.getElementById(item.getAttribute('aria-controls')).hidden=!selected}event('program_group_select',{group:tab.dataset.group})}groupTabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectGroup(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%groupTabs.length;if(e.key==='ArrowLeft')next=(i+groupTabs.length-1)%groupTabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=groupTabs.length-1;if(next!==undefined){e.preventDefault();selectGroup(groupTabs[next]);groupTabs[next].focus()}})});
// HTML is rendered by this buildless template: resolve incoming section links after render.
if(location.hash){requestAnimationFrame(()=>{let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{return}const target=document.getElementById(id);if(target)target.scrollIntoView({behavior:'instant',block:'start'})})}
